script.setup:
// Sand Spline — a port of Anders Hoff's (inconvergent) sand-spline (MIT), Python → JS + WebGL2.
// Ported from modules/sandSpline.py (SandSpline.__next__), modules/helpers.py (_rnd_interpolate) and the
// layouts in main-circles.py (grid of rings), main-circle.py (concentric rings) and main-hlines.py (lines),
// commit a54ef30. Every iteration each control point takes a random step whose size is its own random walk
// (noise[i] += U(-1,1) * i * STP), so one end of a spline stays put while the other end frays; then grains
// are scattered at random positions along the interpolating spline through the control points and painted
// with a tiny alpha, building up like sand. Here the grains are generated on the GPU: control points live in
// a float texture, the vertex shader picks a random arc-length position per grain and evaluates the curve.
// (scipy's splprep/splev cubic spline is replaced by a chord-length Catmull-Rom spline — also interpolating.)
const gl = ctx.gl;
const s = ctx.state;
const floatOK = !!gl.getExtension("EXT_color_buffer_float");
const MAXP = 160;      // control points per spline (originals use 4..150)
const MAXS = 512;      // splines per piece

// --- programs ---------------------------------------------------------------------------------------------
const grainVs = `#version 300 es
precision highp float;
precision highp sampler2D;
uniform sampler2D u_ctrl;     // row = spline, texel = control point: (x, y, cumulative chord length, -)
uniform sampler2D u_info;     // texel x = spline: (point count, total length, color index, grain count)
uniform int u_grains;         // grain slots per spline
uniform float u_seed;
uniform vec2 u_center;        // pixels
uniform float u_unit;         // pixels per world unit
uniform vec2 u_resolution;
uniform vec3 u_pal[5];
uniform float u_alpha;
out vec4 v_col;
uint hash(uint x) { x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16; return x; }
float rnd(uint a) { return float(hash(a) >> 8) / 16777216.0; }
vec2 cp(int sp, int i, int n) { return texelFetch(u_ctrl, ivec2(clamp(i, 0, n - 1), sp), 0).xy; }
float cl(int sp, int i) { return texelFetch(u_ctrl, ivec2(i, sp), 0).z; }
void main() {
  int sp = gl_VertexID / u_grains, g = gl_VertexID - sp * u_grains;
  vec4 info = texelFetch(u_info, ivec2(sp, 0), 0);
  int n = int(info.x);
  gl_PointSize = 1.0;
  if (n < 2 || float(g) >= info.w) { gl_Position = vec4(2.0, 2.0, 0.0, 1.0); return; }
  // random position along the curve, uniform in chord length (splprep's u is chord-length too)
  float u = rnd(uint(gl_VertexID) * 2654435761u ^ uint(u_seed)) * info.y;
  int lo = 0, hi = n - 1;
  for (int k = 0; k < 8; k++) { int mid = (lo + hi) / 2; if (cl(sp, mid) <= u) lo = mid; else hi = mid; }
  float c0 = cl(sp, lo), c1 = cl(sp, lo + 1);
  float t = c1 > c0 ? clamp((u - c0) / (c1 - c0), 0.0, 1.0) : 0.0;
  vec2 p0 = cp(sp, lo - 1, n), p1 = cp(sp, lo, n), p2 = cp(sp, lo + 1, n), p3 = cp(sp, lo + 2, n);
  vec2 p = 0.5 * (2.0 * p1 + (p2 - p0) * t + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * t * t + (3.0 * p1 - p0 - 3.0 * p2 + p3) * t * t * t);
  vec2 px = u_center + p * u_unit;
  gl_Position = vec4(px / u_resolution * 2.0 - 1.0, 0.0, 1.0);
  v_col = vec4(u_pal[int(info.z) % 5] * u_alpha, u_alpha);
}`;
const grainFs = `#version 300 es
precision highp float;
in vec4 v_col;
out vec4 outColor;
void main() { outColor = v_col; }`;
// The sand texture holds, per pixel, the sum of alpha*color (rgb) and alpha (a). On light paper the grains
// absorb (1 - color) like pigment; on dark ground they glow.
const viewFs = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform sampler2D u_sand;
uniform vec2 u_resolution;
uniform float u_dark, u_fade, u_time;
uniform vec3 u_paper;
float h(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
  vec4 a = texture(u_sand, v_uv) * u_fade;
  vec2 q = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);
  float vig = 1.0 - 0.35 * dot(q, q);
  float grainNoise = (h(gl_FragCoord.xy) - 0.5) * 0.03;
  vec3 light = u_paper * vig * exp(-2.2 * max(a.a - a.rgb, vec3(0.0))) + grainNoise;
  vec3 ground = vec3(0.035, 0.035, 0.045) * vig;
  vec3 dark = ground + (1.0 - exp(-1.6 * a.rgb)) * 1.05 + grainNoise * 0.5;
  outColor = vec4(mix(light, dark, u_dark), 1.0);
}`;
s.grainProg = ctx.utils.createProgram(grainVs, grainFs);
s.viewProg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, viewFs);
s.vao = gl.createVertexArray();
s.floatOK = floatOK;
s.MAXP = MAXP; s.MAXS = MAXS;
s.ctrlData = new Float32Array(MAXP * MAXS * 4);
s.infoData = new Float32Array(MAXS * 4);
const texOpts = { internalFormat: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT, filter: gl.NEAREST };
s.ctrlTex = ctx.utils.uploadDataTexture(gl, null, MAXP, MAXS, s.ctrlData, texOpts);
s.infoTex = ctx.utils.uploadDataTexture(gl, null, MAXS, 1, s.infoData, texOpts);
s.texOpts = texOpts;

// --- palettes (on paper: inks; on dark ground: light) -------------------------------------------------------
s.palettes = [
  { name: "Ink", dark: 0, colors: [[0.0, 0.05, 0.12], [0.02, 0.32, 0.38], [0.05, 0.12, 0.25], [0.0, 0.0, 0.0], [0.1, 0.45, 0.5]] },
  { name: "Ember", dark: 1, colors: [[1.0, 0.55, 0.2], [1.0, 0.85, 0.55], [0.95, 0.3, 0.25], [1.0, 0.7, 0.35], [0.9, 0.9, 0.85]] },
  { name: "Rust & indigo", dark: 0, colors: [[0.55, 0.12, 0.05], [0.1, 0.12, 0.35], [0.75, 0.35, 0.1], [0.05, 0.05, 0.1], [0.3, 0.1, 0.25]] },
  { name: "Glacier", dark: 1, colors: [[0.45, 0.85, 1.0], [0.8, 0.95, 1.0], [0.35, 0.55, 1.0], [0.7, 0.6, 1.0], [1.0, 1.0, 1.0]] },
];

const TWOPI = Math.PI * 2;
const randint = (a, b) => a + Math.floor(Math.random() * (b - a));
// A spline: fixed guide (where it is drawn), control points relative to the guide, per-point noise and scale.
function makeSpline(gx, gy, path, stp, color, grains) {
  const n = path.length / 2;
  const scale = new Float64Array(n);
  for (let i = 0; i < n; i++) scale[i] = i * stp; // scale = arange(pnum) * STP
  return { gx, gy, path: Float64Array.from(path), noise: new Float64Array(n), scale, n, color, grains };
}
const ring = (pnum, r) => {
  const a0 = Math.random() * TWOPI, p = [];
  for (let i = 0; i < pnum; i++) { const a = a0 + (i / (pnum - 1)) * TWOPI; p.push(Math.cos(a) * r, Math.sin(a) * r); }
  return p;
};
s.ring = ring;
s.makeSpline = makeSpline;
// Layouts in world units: the short side of the canvas spans 1.0, centered at 0. STP values are scaled up
// from the originals (which run for hours on 5000-10000 px canvases) so a piece unfolds in ~20 s.
s.layouts = [
  // main-circles.py: a grid of small rings, 10..150 control points each
  (aw, ah, drift) => {
    const EDGE = 0.08, short = Math.min(aw, ah), nShort = 7;
    const step = (short * (1 - 2 * EDGE)) / (nShort - 1), leap = step * 0.5 * 0.75;
    const nx = Math.max(1, Math.floor((aw - 2 * EDGE * short) / step + 1e-6) + 1);
    const ny = Math.max(1, Math.floor((ah - 2 * EDGE * short) / step + 1e-6) + 1);
    const ox = -((nx - 1) * step) / 2, oy = -((ny - 1) * step) / 2, out = [];
    for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
      const pnum = randint(10, 150);
      out.push(makeSpline(ox + i * step, oy + j * step, ring(pnum, leap), (drift * leap) / 15000, (i + j * 3) % 5, 1600));
    }
    return out;
  },
  // main-circle.py: 30 concentric rings of 15..100 control points around one center
  (aw, ah, drift) => {
    const R = Math.min(aw, ah) * 0.5 * 0.86, out = [];
    for (let k = 0; k < 30; k++) {
      const pnum = randint(15, 100), r = R * (0.2 + Math.random() * 0.8);
      out.push(makeSpline(0, 0, ring(pnum, r), 3e-6 * drift, k % 5, Math.round(9000 * r / R)));
    }
    return out;
  },
  // main-hlines.py: horizontal lines, the i-th with 4 + i control points, so lower lines fray more
  (aw, ah, drift) => {
    const EDGE = 0.08, rows = Math.round(48 * Math.sqrt(ah / Math.min(aw, ah))), out = [];
    const half = (aw * (1 - 2 * EDGE)) / 2;
    for (let i = 0; i < rows; i++) {
      const y = (ah / 2) * (1 - 2 * EDGE) * (1 - (2 * i) / (rows - 1));
      const pnum = 4 + Math.round(i * 60 / rows), p = [];
      for (let k = 0; k < pnum; k++) p.push(-half + (2 * half * k) / (pnum - 1), 0);
      out.push(makeSpline(0, y, p, 1.6e-6 * drift, i % 5, Math.round(5000 * aw / Math.min(aw, ah))));
    }
    return out;
  },
];
s.layoutNames = ["Grid of rings", "Concentric rings", "Lines"];

// One iteration of SandSpline.__next__: noise random-walks, every control point steps in a random direction.
s.stepSpline = (sp) => {
  const { path, noise, scale, n } = sp;
  for (let i = 0; i < n; i++) {
    noise[i] += (1 - 2 * Math.random()) * scale[i];
    const a = Math.random() * TWOPI;
    path[2 * i] += Math.cos(a) * noise[i];
    path[2 * i + 1] += Math.sin(a) * noise[i];
  }
};

s.started = false;
s.piece = -1;
s.wasDown = false;
s.iter = 0;
s.seed = 1;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const S = Math.min(w, h), aw = w / S, ah = h / S;
const PIECE = 1300; // iterations per piece (~22 s at one iteration per frame)

const newPiece = () => {
  s.piece++;
  const mode = u.u_layout >= 0 && u.u_layout < 3 ? Math.round(u.u_layout) : [2, 1, 0][s.piece % 3];
  // Auto: lines on dark first, then rings on paper, and so on
  s.pal = u.u_palette >= 0 ? s.palettes[Math.round(u.u_palette)] : s.palettes[[1, 0, 2, 3][s.piece % 4]];
  s.splines = s.layouts[mode](aw, ah, u.u_drift);
  s.mode = mode;
  s.iter = 0; s.phase = "draw"; s.phaseT = 0; s.fade = 1;
  s.layoutKey = `${u.u_layout}|${u.u_palette}`;
  s.clear = true;
};

// sand target: canvas-sized, rebuilt (and the piece re-laid out) when the size changes
if (!s.sand || ctx.resized || s.sand.width !== w || s.sand.height !== h) {
  const fmt = s.floatOK ? { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.NEAREST }
    : { internalFormat: gl.RGBA8, format: gl.RGBA, type: gl.UNSIGNED_BYTE, filter: gl.NEAREST };
  if (!s.sand) s.sand = ctx.utils.createPingPong(w, h, fmt); else s.sand.resize(w, h);
  s.piece = Math.max(-1, s.piece - 1);
  newPiece();
}
if (u.u_new || s.layoutKey !== `${u.u_layout}|${u.u_palette}`) newPiece();

// click: drop a new fraying ring where the pointer is (y down in ctx.mouse)
if (ctx.mouseDown && !s.wasDown && s.splines.length < s.MAXS && s.phase === "draw") {
  const r = 0.03 + Math.random() * 0.09, pnum = 40 + Math.floor(Math.random() * 110);
  const sp = s.makeSpline((ctx.mouse[0] - 0.5) * aw, (0.5 - ctx.mouse[1]) * ah, s.ring(pnum, r), (u.u_drift * r) / 30000, Math.floor(Math.random() * 5), Math.round(1600 * r / 0.03));
  s.splines.push(sp);
  s.iter = Math.min(s.iter, PIECE - 400); // give it time to fray
}
s.wasDown = ctx.mouseDown;

const dt = Math.min(ctx.dt, 0.1);
s.phaseT += dt;
let iters = 0;
if (s.phase === "draw") {
  // the first frame lays down half a second of iterations so the sand is visible at once
  // 60 iterations a second times Speed, whatever the display rate
  s.acc = Math.min((s.acc ?? 0) + dt * 60 * u.u_speed, 8);
  iters = Math.floor(s.acc); s.acc -= iters;
  if (s.iter === 0) iters = Math.max(iters, 30);
  if (s.iter >= PIECE) { s.phase = "hold"; s.phaseT = 0; iters = 0; }
} else if (s.phase === "hold") {
  if (s.phaseT > 2.5) { s.phase = "fade"; s.phaseT = 0; }
} else if (s.phase === "fade") {
  s.fade = Math.max(0, 1 - s.phaseT / 1.2);
  if (s.fade <= 0) newPiece();
}

const ctrl = s.ctrlData, info = s.infoData, MAXP = s.MAXP, n = s.splines.length;
let maxG = 1;
for (const sp of s.splines) maxG = Math.max(maxG, sp.grains);
// grains are drawn at canvas resolution: keep the look the same at any size
const alpha = 0.0016 * [0.7, 0.4, 1][s.mode] * u.u_grain * Math.pow(S / 720, 1.0);

gl.bindFramebuffer(gl.FRAMEBUFFER, s.sand.read().framebuffer);
gl.viewport(0, 0, w, h);
if (s.clear) { gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT); s.clear = false; }
if (iters > 0) {
  gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
  gl.useProgram(s.grainProg);
  const pal = s.pal.colors.flat();
  for (let it = 0; it < iters; it++) {
    for (let k = 0; k < n; k++) {
      const sp = s.splines[k];
      s.stepSpline(sp);
      let len = 0;
      const base = k * MAXP * 4, p = sp.path;
      for (let i = 0; i < sp.n; i++) {
        if (i > 0) len += Math.hypot(p[2 * i] - p[2 * i - 2], p[2 * i + 1] - p[2 * i - 1]);
        ctrl[base + i * 4] = sp.gx + p[2 * i];
        ctrl[base + i * 4 + 1] = sp.gy + p[2 * i + 1];
        ctrl[base + i * 4 + 2] = len;
      }
      info[k * 4] = sp.n; info[k * 4 + 1] = len; info[k * 4 + 2] = sp.color;
      // more grains on a longer (frayed) curve, like INUM grains over a curve drawn at 10000 px
      info[k * 4 + 3] = Math.min(maxG, sp.grains);
    }
    gl.bindTexture(gl.TEXTURE_2D, s.ctrlTex);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, MAXP, n, gl.RGBA, gl.FLOAT, ctrl);
    gl.bindTexture(gl.TEXTURE_2D, s.infoTex);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, n, 1, gl.RGBA, gl.FLOAT, info);
    ctx.utils.bindTexture(s.grainProg, "u_ctrl", s.ctrlTex, 0);
    ctx.utils.bindTexture(s.grainProg, "u_info", s.infoTex, 1);
    ctx.utils.setUniforms(s.grainProg, {
      u_grains: maxG, u_seed: (s.seed = (s.seed * 1103515245 + 12345) % 16777213), u_center: [w / 2, h / 2], u_unit: S,
      u_resolution: [w, h], u_pal: pal, u_alpha: alpha,
    });
    gl.bindVertexArray(s.vao);
    gl.drawArrays(gl.POINTS, 0, n * maxG);
    gl.bindVertexArray(null);
    s.iter++;
  }
  gl.disable(gl.BLEND);
}
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.viewProg);
ctx.utils.bindTexture(s.viewProg, "u_sand", s.sand.read().texture, 0);
ctx.utils.drawFullscreen(s.viewProg, { u_dark: s.pal.dark, u_fade: s.fade, u_paper: [0.96, 0.94, 0.89] });

ctx.publish("layout", s.layoutNames[s.mode]);
ctx.publish("palette", s.pal.name);
ctx.publish("splines", n);
ctx.publish("piece %", Math.round((100 * s.iter) / PIECE));

script.cleanup:
const s = ctx.state, gl = ctx.gl;
gl.deleteTexture(s.ctrlTex); gl.deleteTexture(s.infoTex);
gl.deleteProgram(s.grainProg); gl.deleteProgram(s.viewProg);
gl.deleteVertexArray(s.vao);
